// src/bot/runtime/ScriptRegistry.ts
class ScriptRegistryImpl {
  metas = new Map;
  changeListeners = new Set;
  register(meta) {
    this.metas.set(meta.name, meta);
    this.notify();
  }
  unregister(name) {
    const removed = this.metas.delete(name);
    if (removed) {
      this.notify();
    }
    return removed;
  }
  notify() {
    for (const listener of this.changeListeners) {
      try {
        listener();
      } catch (err) {
        console.error("[rs2b0t] registry listener error", err);
      }
    }
  }
  list() {
    return [...this.metas.values()];
  }
  get(name) {
    return this.metas.get(name);
  }
  onChange(cb) {
    this.changeListeners.add(cb);
    return () => this.changeListeners.delete(cb);
  }
}
var ScriptRegistry = new ScriptRegistryImpl;

