// src/client/config/target.ts
var LIVE_HOST = "w1.rs2b2t.com";
function resolveTarget(name, locationHost = "", isHttps = false) {
  if (name === "live") {
    return { wsHost: LIVE_HOST, tls: true };
  }
  return { wsHost: locationHost, tls: isHttps };
}
var TARGET_NAME = "local";
var TARGET = typeof window !== "undefined" ? resolveTarget(TARGET_NAME, window.location.host, window.location.protocol === "https:") : resolveTarget(TARGET_NAME);

// src/client/config/loginKey.ts
var BAKED_MODULUS = "";
var EXPONENT = "65537";
var CLIENT_BUNDLE = "/client/client.js";
var modulus = BAKED_MODULUS;
function loginModulus() {
  return BigInt(modulus);
}
function loginExponent() {
  return BigInt(EXPONENT);
}
function parseLoginModulus(text) {
  const match = /^\d{250,}$/.exec(text.trim());
  return match ? match[0] : null;
}
function extractLoginModulus(text) {
  const match = /\d{250,}/.exec(text);
  return match ? match[0] : null;
}
async function readModulus(url, extract) {
  try {
    const res = await fetch(url);
    if (!res.ok) {
      return null;
    }
    return extract(await res.text());
  } catch (_e) {
    return null;
  }
}
async function refreshLoginKey() {
  const next = await readModulus("/loginkey", parseLoginModulus) ?? await readModulus(CLIENT_BUNDLE, extractLoginModulus);
  if (!next || next === modulus) {
    return false;
  }
  modulus = next;
  return true;
}

