// src/bot/api/equipment/Equipment.ts
var Equipment = {
  items() {
    return reader.equipment().map((s) => new InvItem(s));
  },
  contains(name) {
    const wanted = name.toLowerCase();
    return reader.equipment().some((i2) => i2.name?.toLowerCase() === wanted);
  },
  async equip(name) {
    if (Equipment.contains(name)) {
      return true;
    }
    if (Bank.isOpen()) {
      if (!await Bank.close()) {
        return false;
      }
    }
    const item = Inventory.first(name);
    if (!item) {
      return false;
    }
    const op = item.actions().find((o) => /wield|wear|equip/i.test(o));
    if (!op) {
      return false;
    }
    if (!await item.interact(op)) {
      return false;
    }
    return Execution.delayUntil(() => Equipment.contains(name), 3000);
  },
  async unequip(name) {
    const wanted = name.toLowerCase();
    const worn = reader.equipment().find((i2) => i2.name?.toLowerCase() === wanted);
    if (!worn) {
      return true;
    }
    const opIndex2 = worn.ops.findIndex((o) => o?.toLowerCase() === "remove");
    if (opIndex2 === -1) {
      return false;
    }
    await Input.invButton(worn.id, worn.slot, worn.comId, opIndex2 + 1);
    return Execution.delayUntil(() => !Equipment.contains(name), 3000);
  }
};

// src/bot/geometry/distance.ts
function bankDistance(from, bank) {
  const dx = bank.x - from.x;
  const dz = bank.z - from.z;
  return Math.hypot(dx, dz);
}

