// src/bot/api/query/Query.ts
class EntityQuery {
  supplySnaps;
  wrap;
  snapFilters = [];
  entityFilters = [];
  constructor(supplySnaps, wrap) {
    this.supplySnaps = supplySnaps;
    this.wrap = wrap;
  }
  static fromSnapshots(supply, wrap) {
    return new EntityQuery(() => supply(), (s) => wrap(s));
  }
  name(...names) {
    const wanted = names.map((n) => n.trim().toLowerCase());
    this.snapFilters.push((s) => s.name !== null && wanted.includes(s.name.trim().toLowerCase()));
    return this;
  }
  action(action) {
    const wanted = action.toLowerCase();
    this.snapFilters.push((s) => s.ops.some((a) => a != null && a !== "hidden" && a.toLowerCase() === wanted));
    return this;
  }
  within(dist) {
    this.snapFilters.push((s) => s.distance <= dist);
    return this;
  }
  withinOf(origin, dist) {
    const r = Math.max(0, Math.floor(dist));
    this.snapFilters.push((s) => {
      const t = s.tile;
      return Math.max(Math.abs(t.x - origin.x), Math.abs(t.z - origin.z)) <= r;
    });
    return this;
  }
  inside(area) {
    this.snapFilters.push((s) => {
      const t = s.tile;
      return t.x >= area.minX && t.x <= area.maxX && t.z >= area.minZ && t.z <= area.maxZ;
    });
    return this;
  }
  where(pred) {
    this.entityFilters.push(pred);
    return this;
  }
  results() {
    const snaps = this.supplySnaps();
    const out = [];
    for (const s of snaps) {
      if (this.snapFilters.length > 0 && !this.snapFilters.every((f) => f(s))) {
        continue;
      }
      const e = this.wrap(s);
      if (this.entityFilters.length > 0 && !this.entityFilters.every((f) => f(e))) {
        continue;
      }
      out.push(e);
    }
    return out;
  }
  nearest() {
    let best = null;
    for (const e of this.results()) {
      if (!best || e.distance() < best.distance()) {
        best = e;
      }
    }
    return best;
  }
  nearestPreferLocal(preferRadius) {
    const r = Math.max(0, Math.floor(preferRadius));
    const all = this.results();
    if (all.length === 0) {
      return null;
    }
    let pool = all;
    if (r > 0) {
      const local = all.filter((e) => e.distance() <= r);
      if (local.length > 0) {
        pool = local;
      }
    }
    let best = null;
    for (const e of pool) {
      if (!best || e.distance() < best.distance()) {
        best = e;
      }
    }
    return best;
  }
  first() {
    return this.results()[0] ?? null;
  }
  exists() {
    return this.results().length > 0;
  }
  count() {
    return this.results().length;
  }
}

