// src/bot/event/webwalk/geometry/arrival.ts
function walkChebyshev(a, b) {
  const xz = chebyshev(a, b);
  return a.level === b.level ? xz : 1e6 + xz;
}
function isArrived(me, dest, radius, probe) {
  if (me.level !== dest.level) {
    return false;
  }
  const dist = chebyshev(me, dest);
  if (dist > radius) {
    return false;
  }
  if (dist === 0) {
    return true;
  }
  if (probe.canReach(dest)) {
    return true;
  }
  if (probe.walkable(dest)) {
    return false;
  }
  return !probe.probeable(dest) || probe.canReachAdjacent(dest);
}

// src/bot/event/webwalk/walkOpening.ts
var ESCAPE_RADIUS = 14;
var TOWARD_SLACK = 4;
function isOpenableObstacle(name, actions2, obstacles) {
  const n = (name ?? "").toLowerCase();
  return obstacles.some((k) => n.includes(k)) && actions2.some((a) => /^open/i.test(a));
}
function openOp(actions2) {
  return actions2.find((a) => /^open/i.test(a)) ?? null;
}
function towardDest(door, here, dest) {
  const cheb = (a, b) => Math.max(Math.abs(a.x - b.x), Math.abs(a.z - b.z));
  return cheb(door, dest) <= cheb(here, dest) + TOWARD_SLACK;
}
async function walkOpening(dest, radius, obstacles, log) {
  for (let seg = 0;seg < 8; seg++) {
    const here2 = Game.tile();
    if (here2 && isArrived(here2, dest, radius, Reachability.arrivalProbe())) {
      return true;
    }
    await Traversal.walkTo(dest, { radius, timeoutMs: 90000, log: (m) => log?.(`  ${m}`) });
    const after = Game.tile();
    if (after && isArrived(after, dest, radius, Reachability.arrivalProbe())) {
      return true;
    }
    const openableInRange = (l) => isOpenableObstacle(l.name, l.actions(), obstacles) && l.distance() <= ESCAPE_RADIUS && Reachability.canReach(l.tile(), { adjacentOk: true });
    const door = Locs.query().where((l) => openableInRange(l)).where((l) => after === null || towardDest(l.tile(), after, dest)).nearest() ?? Locs.query().where((l) => openableInRange(l)).nearest();
    if (!door) {
      return false;
    }
    const dt = door.tile();
    const cur = Game.tile();
    if (cur && dt.distanceTo(cur) > 1) {
      log?.(`walking to ${door.name} at ${dt.x},${dt.z} to open it`);
      await Traversal.walkTo(dt, { radius: 1, timeoutMs: 45000, log: (m) => log?.(`  ${m}`) });
    }
    const shut = Locs.query().where((l) => l.tile().x === dt.x && l.tile().z === dt.z && isOpenableObstacle(l.name, l.actions(), obstacles)).nearest();
    if (!shut) {
      continue;
    }
    const op = openOp(shut.actions());
    log?.(`opening ${shut.name} at ${dt.x},${dt.z}`);
    if (!await shut.interact(op)) {
      await Execution.delayTicks(2);
      continue;
    }
    await Execution.delayUntil(() => {
      const still = Locs.query().where((l) => l.tile().x === dt.x && l.tile().z === dt.z && isOpenableObstacle(l.name, l.actions(), obstacles)).nearest();
      return still === null;
    }, 4000);
  }
  const here = Game.tile();
  return here !== null && isArrived(here, dest, radius, Reachability.arrivalProbe());
}

// src/bot/api/bank/Banking.ts
var NEARBY_BANK_RADIUS = 14;
