// src/bot/event/webwalk/geometry/lcCoord.ts
function parseLcCoord(raw2) {
  const parts = raw2.trim().split("_").map(Number);
  if (parts.length !== 5 || parts.some((n) => !Number.isFinite(n))) {
    throw new Error(`invalid LostCity coord: ${raw2}`);
  }
  const [level, mx, mz, lx, lz] = parts;
  return {
    level,
    x: mx * 64 + lx,
    z: mz * 64 + lz
  };
}
function packCoord(level, x2, z) {
  return z & 16383 | (x2 & 16383) << 14 | (level & 3) << 28;
}
function packNavPoint(p) {
  return packCoord(p.level, p.x, p.z);
}

// src/bot/event/webwalk/essenceExit.ts
var parse = parseLcCoord;
var ESSENCE_EXIT_RETURNS = {
  aubury: parse("0_50_53_53_9"),
  sedridor: parse("0_48_149_34_36"),
  distentor: parse("0_40_48_31_14"),
  brimstail: parse("0_37_153_22_18"),
  cromperty: parse("0_41_51_60_58")
};
var PACKED_RETURNS = Object.entries(ESSENCE_EXIT_RETURNS).map(([id, tile]) => ({ id, tile, packed: packNavPoint(tile) }));
function essenceReturnIdFromTile(tile) {
  let best = null;
  let bestD = 4;
  for (const [id, t] of Object.entries(ESSENCE_EXIT_RETURNS)) {
    if (t.level !== tile.level) {
      continue;
    }
    const d = Math.max(Math.abs(t.x - tile.x), Math.abs(t.z - tile.z));
    if (d < bestD) {
      bestD = d;
      best = id;
    }
  }
  return best;
}

// src/bot/event/webwalk/essenceSession.ts
var NPC_TO_RETURN = {
  aubury: "aubury",
  sedridor: "sedridor",
  "wizard distentor": "distentor",
  distentor: "distentor",
  "wizard cromperty": "cromperty",
  cromperty: "cromperty",
  brimstail: "brimstail"
};
var sessionReturn;
var harnessOverride;
var EssenceSession = {
  getReturnId() {
    return harnessOverride ?? sessionReturn;
  },
  noteEntry(returnId) {
    sessionReturn = returnId;
  },
  noteEntryFromNpc(name) {
    if (!name) {
      return null;
    }
    const id = NPC_TO_RETURN[name.trim().toLowerCase()];
    if (id) {
      sessionReturn = id;
      return id;
    }
    return null;
  },
  noteEntryFromTransport(transport) {
    const action = (transport.action ?? "").toLowerCase();
    if (action !== "teleport") {
      return null;
    }
    const fromNpc = this.noteEntryFromNpc(transport.locName);
    if (fromNpc) {
      return fromNpc;
    }
    if (transport.locX !== undefined && transport.locZ !== undefined) {
      const atStand = essenceReturnIdFromTile({
        x: transport.locX,
        z: transport.locZ,
        level: 0
      });
      if (atStand) {
        sessionReturn = atStand;
        return atStand;
      }
    }
    return null;
  },
  noteEntryFromCrossingLabel(label) {
    if (!label || !/essence\s*mine/i.test(label)) {
      return null;
    }
    const head = label.split(/→|->/)[0]?.trim() ?? label;
    return this.noteEntryFromNpc(head);
  },
  setHarnessOverride(id) {
    harnessOverride = id;
  },
  clearHarnessOverride() {
    harnessOverride = undefined;
  },
  clear() {
    sessionReturn = undefined;
    harnessOverride = undefined;
  },
  _resetForTests() {
    this.clear();
  }
};

// src/bot/event/webwalk/slashTool.ts
var SLASH_NAME_RE = /\b(scimitar|longsword|sword|dagger|battleaxe|2h\b|two.handed|claws|whip|scythe|halberd|machete|abyssal|silverlight|excalibur|darklight)\b/i;
var WEB_SLASH_KNIFE_NAME = "Knife";
var WEB_SLASHED_NAME = "Slashed web";
function isSlashWeaponName(name) {
  if (!name) {
    return false;
  }
  const n = name.trim();
  if (!n || /^knife$/i.test(n)) {
    return false;
  }
  if (/^(bronze|iron|steel|black|mithril|adamant|rune|dragon)\s+knife$/i.test(n)) {
    return false;
  }
  return SLASH_NAME_RE.test(n);
}
function isContentKnifeName(name) {
  return !!name && /^knife$/i.test(name.trim());
}
function recordsHaveSlashTool(items, worn = {}) {
  for (const [name, count] of Object.entries(items)) {
    if (count > 0 && (isContentKnifeName(name) || isSlashWeaponName(name))) {
      return true;
    }
  }
  for (const [name, count] of Object.entries(worn)) {
    if (count > 0 && (isContentKnifeName(name) || isSlashWeaponName(name))) {
      return true;
    }
  }
  return false;
}
