    items[name.toLowerCase()] = (items[name.toLowerCase()] ?? 0) + item.count;
    items[name.toLowerCase().replace(/\s+/g, "")] = (items[name.toLowerCase().replace(/\s+/g, "")] ?? 0) + item.count;
