function locWithAction(name, op) {
  const wanted = op.toLowerCase();
  return Locs.query().name(name).where((loc) => loc.actions().some((action) => action.toLowerCase() === wanted)).nearest();
}
function bankStand(booth) {
  const me = reader.worldTile();
  const neighbours = [
    { x: booth.x + 1, z: booth.z, level: booth.level },
    { x: booth.x - 1, z: booth.z, level: booth.level },
    { x: booth.x, z: booth.z + 1, level: booth.level },
    { x: booth.x, z: booth.z - 1, level: booth.level }
  ];
  const reachable = neighbours.filter((t) => Reachability.canReach(t));
  if (reachable.length === 0) {
    return null;
  }
  if (!me) {
    return reachable[0];
  }
  const cheb = (t) => Math.max(Math.abs(t.x - me.x), Math.abs(t.z - me.z));
  return reachable.sort((a, b) => cheb(a) - cheb(b))[0];
}
