var WORKSHOP_Z_MAX = 9950;
var WORKSHOP_X_MIN = 2690;
var WORKSHOP_X_MAX = 2760;
function ewArea(tile) {
  if (!tile) {
    return "unknown";
  }
  if (tile.level === 0 && tile.x >= WORKSHOP_X_MIN && tile.x <= WORKSHOP_X_MAX && tile.z >= WORKSHOP_Z_MIN && tile.z <= WORKSHOP_Z_MAX) {
    return "workshop";
  }
  if (tile.x >= 2680 && tile.x <= 2760 && tile.z >= 3460 && tile.z <= 3520) {
    return "seers";
  }
  return "elsewhere";
}

// src/bot/api/ai/quests/defs/elementalworkshop/journal.ts
var ELEMENTAL_WORKSHOP_QUEST = "Elemental Workshop";
var EW_STAGE = {
  NOT_STARTED: 0,
  READ_BOOK: 1,
  SLASHED: 2,
  ENTERED: 3,
  COMPLETE: 4
};
var EW_FLAG = {
  WATER: "water-flowing",
  BELLOWS: "bellows-fixed",
  FURNACE: "furnace-lit",
  MADE_BAR: "made-bar"
};
function normalize(lines) {
  return (typeof lines === "string" ? lines : lines.join(" ")).replace(/@[a-z0-9]{3}@/gi, " ").replace(/[|\s]+/g, " ").trim().toLowerCase();
}
function readFlags(text) {
  const flags = new Set;
  if (text.includes("waterwheel in the northern water") || text.includes("water wheel in the northern water") || text.includes("get the waterwheel") || text.includes("get the water wheel")) {
    flags.add(EW_FLAG.WATER);
  }
  if (text.includes("bellows in the eastern air area are now fixed") || text.includes("stitch some leather")) {
    flags.add(EW_FLAG.BELLOWS);
  }
  if (text.includes("lit the furnace with lava") || text.includes("using the stone bowl")) {
    flags.add(EW_FLAG.FURNACE);
  }
  if (text.includes("made a bar from the elemental ore") || text.includes("just need to make something from it")) {
    flags.add(EW_FLAG.MADE_BAR);
  }
  return flags;
}
function readStage(text) {
  if (text.includes("quest complete!")) {
    return EW_STAGE.COMPLETE;
  }
  if (text.includes("secret door in the seers village smithy") || text.includes("there is obviously lots to do here") || text.includes("made a bar from the elemental ore") || text.includes("managed to get the waterwheel") || text.includes("managed to get the water wheel") || text.includes("bellows in the eastern air area") || text.includes("lit the furnace with lava")) {
    return EW_STAGE.ENTERED;
  }
  if (text.includes("cutting open the spine of the book") || text.includes("key hidden under the leather binding")) {
    return EW_STAGE.SLASHED;
  }
  if (text.includes("found a battered book") || text.includes("tells of magic ore and a workshop")) {
    return EW_STAGE.READ_BOOK;
  }
  if (text.includes("i can start this quest by reading a")) {
    return EW_STAGE.NOT_STARTED;
  }
  return;
}
function parseElementalWorkshopJournal(lines) {
  const text = normalize(lines);
  const stage = readStage(text);
  if (stage === undefined) {
    return;
  }
  return { stage, flags: readFlags(text) };
}
async function readElementalWorkshopProgress() {
  const status = Quests.status(ELEMENTAL_WORKSHOP_QUEST);
  if (status === "complete") {
    return { stage: EW_STAGE.COMPLETE, flags: new Set };
  }
  if (status === "notStarted") {
    return { stage: EW_STAGE.NOT_STARTED, flags: new Set };
  }
  if (status !== "inProgress") {
    return;
  }
  const progress = parseElementalWorkshopJournal(await Quests.journal(ELEMENTAL_WORKSHOP_QUEST));
  if (reader.modals().main !== -1) {
    actions.closeModal();
    await Execution.delayTicks(1);
  }
  return progress;
}

