  return fromBank(snap, EW_ITEM.KNIFE, 1) ?? (bankWeapon ? fromBank(snap, bankWeapon, 1) : null) ?? { kind: "grabGround", item: EW_ITEM.KNIFE.name, anchor: KNIFE_SPAWN, waitIfMissing: true };
