var OPPORTUNISTIC_FOODS = new Set(foodForms("Cake"));
function resolveConsumeAction(actions2) {
  for (const wanted of ["Eat", "Drink"]) {
    const action = actions2.find((candidate) => candidate.toLowerCase() === wanted.toLowerCase());
    if (action)
      return action;
  }
  return null;
}
function selectSustainConsumable(items, foods, hp, maxHp) {
  const allowed = new Set(foods.map((food) => food.trim().toLowerCase()).filter(Boolean));
  const candidates = [];
  for (const item of items) {
    const name = item.name?.trim().toLowerCase() ?? "";
    const policyFood = allowed.has(name);
    if (!policyFood && !OPPORTUNISTIC_FOODS.has(name)) {
      continue;
    }
    const action = resolveConsumeAction(item.actions());
    if (!action) {
      continue;
    }
    candidates.push({ item, action, heal: foodHealAmount(name), policyFood });
  }
  const fitting = hp > 0 && maxHp > 0 ? candidates.find((candidate) => hp + candidate.heal <= maxHp) : undefined;
  const emergency = (candidate) => shouldEatToUseFood({ hp, maxHp, heal: candidate.heal, foodCount: 1 });
  const selected = fitting ?? candidates.find((candidate) => candidate.policyFood && emergency(candidate));
  return selected ? { item: selected.item, action: selected.action } : null;
}
function resolveSustainPolicy(configuredFood, quest) {
  const foods = [];
  const seen = new Set;
  for (const candidate of [...quest?.foods ?? [], configuredFood]) {
    const food = candidate?.trim();
    if (!food) {
      continue;
    }
    for (const form of foodForms(food)) {
      if (seen.has(form)) {
        continue;
      }
      seen.add(form);
      foods.push(form);
    }
  }
  return { foods };
}
