// src/bot/scripts/AIOQuester/QuestJournalHud.ts
var FOOTER_H = 28;
var QUEUE_COLUMNS = 2;
var DIM = "#5a4630";
var INK = "#2c1c0c";
var GOLD = "#e8c35b";
var SEAL = "#2d4a8c";
var PARCHMENT = "rgba(214, 190, 132, 0.96)";
var HEADER_BG = "rgba(72, 42, 14, 0.96)";
var BUTTON_FACE = "#f5ebd0";
var JOURNAL_PALETTE = {
  bg: "rgba(210, 186, 130, 0.0)",
  bgWidget: "rgba(72, 42, 12, 0.95)",
  bgWidgetHot: "rgba(140, 90, 28, 0.98)",
  fg: INK,
  fgDim: DIM,
  widgetFg: BUTTON_FACE,
  border: "rgba(180, 140, 50, 0.55)"
};
function paintQuestJournal(ctx, model) {
  const maxed = isQuestHudMaximized(paintState.get(QUEST_HUD_MAX_KEY, QUEST_HUD_START_VALUE));
  const tab = questHudTab(paintState.get("tabs:aio", "Current"));
  const height = maxed ? questHudMaximizedHeight({
    tab,
    stepDesc: model.stepDesc,
    blockedCount: blockedLines(model.rows, 40).length
  }) : undefined;
  const dock = questJournalDock(maxed, height);
  const toggle = questHudToggleRect(dock);
  drawParchment(ctx, dock);
  drawHeader(ctx, dock, model, maxed, toggle);
  const p = Paint.begin(ctx, {
    dock,
    accent: GOLD,
    header: "none",
    fill: false,
    palette: JOURNAL_PALETTE
  });
  if (p.clickable("btn:hudtoggle", toggle)) {
    paintState.set(QUEST_HUD_MAX_KEY, maxed ? "0" : "1");
  }
  p.advance(QUEST_HUD_HEADER_H);
  if (!maxed) {
    paintMinimized(p, model);
  } else {
    paintMaximized(p, model);
  }
  p.gap(3);
  const clicked = p.buttons([
    { id: "pause", label: model.runnerState === "paused" ? "Resume" : "Pause" },
    { id: "skip", label: "Skip quest" },
    { id: "stop", label: "Stop" }
  ]);
  if (clicked === "pause") {
    if (ScriptRunner.state === "paused") {
      ScriptRunner.resume();
    } else {
      ScriptRunner.pause();
    }
  } else if (clicked === "skip") {
    model.onSkip();
  } else if (clicked === "stop") {
    ScriptRunner.stop("Stop button (quest overlay)");
  }
  p.end();
}
var QUEST_HUD_START_VALUE = "0";
function paintMinimized(p, model) {
  const running = model.rows.find((r) => r.id === model.runningId);
  const questMins = (Date.now() - model.questSince) / 60000;
  p.text(clipText(model.stepDesc || model.status, p.cols()), INK);
  p.cells([
    { text: `QP ${model.qp}`, weight: 1, color: DIM },
    { text: fmtDuration(questMins), weight: 1, color: DIM },
    { text: clipText(questHudActivity(model.status, running?.name), 16), weight: 1.6, color: "#6b1d1d" }
  ]);
}
function paintMaximized(p, model) {
  const rows = model.rows;
  const running = rows.find((r) => r.id === model.runningId);
  const tab = p.tabs("aio", ["Current", "Queue", "Blocked", "Session"]);
  if (tab === "Queue") {
    const sum = queueSummary(rows);
    const lines = rows.map((r) => {
      const e = queueEntry(r);
      return { text: `${e.icon} ${e.name}`, color: journalInk(e.colour, r.status) };
    });
    p.grid("aioqueue", lines, QUEUE_COLUMNS, {
      reserve: FOOTER_H,
      focus: focusRow(rows, model.runningId),
      footer: `QP ${model.qp} · done ${sum.done}/${sum.total} · stuck ${sum.stuck}`
    });
    return;
  }
  if (tab === "Current") {
    const stepMins = (Date.now() - model.stepSince) / 60000;
    const questMins = (Date.now() - model.questSince) / 60000;
    p.cells([
      { text: `Quest: ${questHudActivity(model.status, running?.name)}`, weight: 2, color: running || model.status === "Money making" ? "#6b1d1d" : DIM },
      { text: `On quest: ${fmtDuration(questMins)}`, weight: 1 }
    ]);
    p.cells([
      { text: `On step: ${fmtDuration(stepMins)}`, weight: 1 },
      { text: `Session: ${fmtDuration((Date.now() - model.startedAt) / 60000)}`, weight: 1 }
    ]);
    p.text("Step", DIM);
    for (const line of wrapText(model.stepDesc || "—", p.cols(), 2).slice(0, 5)) {
      p.text(line, INK);
    }
    p.gap(2);
    p.cells([
      { text: `No-progress: ${model.noProgress}`, weight: 1 },
      { text: `Parked: ${model.parkedCount}`, weight: 1 },
      { text: `Food: ${model.foodLabel}`, weight: 1.6 }
    ]);
    return;
  }
  if (tab === "Blocked") {
    const lines = blockedLines(rows, p.cols()).map((l) => ({
      text: l.text,
      color: l.dim ? DIM : QUEUE_COLOUR.BLOCKED
    }));
    if (lines.length === 0) {
      p.text("nothing blocked", DIM);
    } else {
      p.fill("aioblocked", lines, { reserve: FOOTER_H });
    }
    return;
  }
  const mins = (Date.now() - model.startedAt) / 60000;
  p.cells([
    { text: `Runtime: ${fmtDuration(mins)}`, weight: 1.4 },
    { text: `Completed: ${model.completed}`, weight: 1.2 },
    { text: `Deaths: ${model.deaths}`, weight: 1 }
  ]);
  p.cells([
    { text: `QP: ${model.qp}`, weight: 1.4 },
    { text: `QP gained: ${model.qpGained}`, weight: 1.2 },
    { text: `Parked: ${model.parkedCount}`, weight: 1 }
  ]);
  p.cells([
    { text: `State: ${model.runnerState}${model.skipRequested ? " (skip pending)" : ""}`, weight: 1.4 },
    { text: `Loadout: ${model.loadout}`, weight: 1.6 }
  ]);
  p.gap(4);
  for (const line of wrapText(model.stepDesc || model.status, p.cols(), 2).slice(0, 3)) {
    p.text(line, DIM);
  }
}
function journalInk(colour, status) {
  if (status === "RUNNING") {
    return "#6b1d1d";
  }
  if (status === "READY") {
    return INK;
  }
  return colour;
}
function drawParchment(ctx, dock) {
  ctx.save();
  ctx.fillStyle = "rgba(28, 18, 8, 0.55)";
  ctx.fillRect(dock.x + 2, dock.y + 2, dock.w, dock.h);
  ctx.fillStyle = PARCHMENT;
  ctx.fillRect(dock.x, dock.y, dock.w, dock.h);
  ctx.strokeStyle = "#8a5a1e";
  ctx.lineWidth = 2;
  ctx.strokeRect(dock.x + 1, dock.y + 1, dock.w - 2, dock.h - 2);
  ctx.strokeStyle = GOLD;
  ctx.lineWidth = 1;
  ctx.strokeRect(dock.x + 3.5, dock.y + 3.5, dock.w - 7, dock.h - 7);
  ctx.fillStyle = HEADER_BG;
  ctx.fillRect(dock.x, dock.y, dock.w, QUEST_HUD_HEADER_H);
  ctx.strokeStyle = GOLD;
  ctx.beginPath();
  ctx.moveTo(dock.x + 4, dock.y + QUEST_HUD_HEADER_H - 0.5);
  ctx.lineTo(dock.x + dock.w - 4, dock.y + QUEST_HUD_HEADER_H - 0.5);
  ctx.stroke();
  ctx.restore();
}
function drawHeader(ctx, dock, model, maxed, toggle) {
  const cx = dock.x + 14;
  const cy = dock.y + QUEST_HUD_HEADER_H / 2;
  drawQuestStar(ctx, cx, cy, 8);
  ctx.save();
  ctx.font = "bold 11px monospace";
  ctx.textBaseline = "middle";
  ctx.fillStyle = GOLD;
  const running = model.rows.find((r) => r.id === model.runningId);
  const title = maxed ? `Benny's Fixed Quester V2` : clipText(questHudActivity(model.status, running?.name), 18);
  ctx.fillText(title, dock.x + 26, cy + 1);
  drawToggleButton(ctx, toggle, maxed);
  ctx.restore();
}
function drawToggleButton(ctx, r, maxed) {
  const hovered = paintState.isHovered(r);
  ctx.save();
  if (maxed) {
    ctx.fillStyle = hovered ? "rgba(110, 70, 24, 0.98)" : "rgba(50, 30, 12, 0.96)";
    ctx.strokeStyle = GOLD;
    ctx.fillRect(r.x, r.y, r.w, r.h);
    ctx.strokeRect(r.x + 0.5, r.y + 0.5, r.w - 1, r.h - 1);
    ctx.fillStyle = GOLD;
  } else {
    ctx.fillStyle = hovered ? "#ffe08a" : GOLD;
    ctx.strokeStyle = "#5c3a10";
    ctx.fillRect(r.x, r.y, r.w, r.h);
    ctx.strokeRect(r.x + 0.5, r.y + 0.5, r.w - 1, r.h - 1);
    ctx.fillStyle = INK;
  }
  ctx.font = "bold 12px monospace";
  ctx.textBaseline = "middle";
  ctx.textAlign = "center";
  ctx.fillText(questHudToggleLabel(maxed), r.x + r.w / 2, r.y + r.h / 2 + 1);
  ctx.restore();
}
function drawQuestStar(ctx, cx, cy, outer) {
  const pts = questStarPoints(cx, cy, outer, outer * 0.42);
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, outer + 2, 0, Math.PI * 2);
  ctx.fillStyle = SEAL;
  ctx.fill();
  ctx.strokeStyle = GOLD;
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(pts[0].x, pts[0].y);
  for (const pt of pts.slice(1)) {
    ctx.lineTo(pt.x, pt.y);
  }
  ctx.closePath();
  ctx.fillStyle = GOLD;
  ctx.fill();
  ctx.strokeStyle = "#6b4a12";
  ctx.lineWidth = 0.75;
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(cx, cy, outer * 0.22, 0, Math.PI * 2);
  ctx.fillStyle = "#f5e6a8";
  ctx.fill();
  ctx.restore();
}

// src/bot/scripts/AIOQuester/AIOQuester.ts
var DEATH_RE = /oh dear.*you are dead/i;
var QUEST_OPTION_LABELS = Object.fromEntries(QUEST_DEFS.map((def2) => [def2.record.id, def2.record.name]));
var QUEST_OPTION_IDS = QUEST_DEFS.map((def2) => def2.record.id).sort((a, b) => QUEST_OPTION_LABELS[a].localeCompare(QUEST_OPTION_LABELS[b]));
var FALLBACK_FOOD = "Lobster";
var AIO_SETTINGS = {
  quests: {
    type: "string[]",
    default: [],
    options: QUEST_OPTION_IDS,
    optionLabels: QUEST_OPTION_LABELS,
    label: "Quest queue (empty = all)",
    help: "which implemented quests to complete; leave empty to run every implemented quest. Tick order does not matter, the queue runs the built-in order that puts prerequisites first",
    selectGroups: [{
      label: "F2P Quests",
      options: F2P_QUEST_IDS.filter((id) => QUEST_OPTION_IDS.includes(id))
    }],
    livePicker: {
      label: "Quests I can do",
      pick: () => pickQuestsICanDo(QUEST_OPTION_IDS)
    }
  },
  loadout: LOADOUT_SETTING,
  food: {
    type: "string",
    default: FALLBACK_FOOD,
    options: FOOD_OPTIONS,
    label: "Food",
    help: "what the engine withdraws for any quest declaring a food count, and what the bot eats; this wins over any food the chosen loadout carries"
  },
  arravGang: {
    type: "string",
    default: "random",
    options: [...ARRAV_GANG_OPTIONS],
    label: "Shield of Arrav gang",
    group: "Shield of Arrav",
    help: "which gang to join; random picks one from a hash of the character name, so the same character always picks the same gang"
  },
  arravPartner: {
    type: "string",
    default: "",
    label: "Shield of Arrav partner",
    group: "Shield of Arrav",
    help: "character name of the bot running the other gang; the quest cannot be finished alone unless a certificate is already banked"
  },
  arravCerts: {
    type: "number",
    default: 2,
    min: 1,
    max: 50,
    label: "Shield of Arrav certificates",
    group: "Shield of Arrav",
    help: "how many certificates to mint before redeeming one; each pair costs both bots a fresh shield half, and the surplus banks for other bots"
  },
  heroPartner: {
    type: "string",
    default: "",
    label: "Hero's Quest partner",
    group: "Hero's Quest",
    help: "character name of the bot running the other gang; the master thief armband cannot be earned alone, and the gang itself comes from the Shield of Arrav setting"
  },
  legendsReward: {
    type: "string",
    default: "Prayer",
    options: [...LEGENDS_REWARD_OPTIONS],
    label: "Legends Quest reward",
    group: "Legends Quest",
    help: "which skill Radimus' four training sessions go into; Prayer by default, as the quest's own three demon fights are survived on Protect from Melee"
  },
  verbose: {
    type: "boolean",
    default: true,
    label: "Verbose step log",
    help: "log every engine tick with the step, attempt count, elapsed time and inventory delta, and stop de-duplicating sub-steps; off still heartbeats a repeating step"
  }
};

class AIOQuester extends TaskBot {
  loopDelay = 600;
  status = "starting";
  picked = new Set;
  rows = [];
  runningId = null;
  stepDesc = ", ";
  noProgress = 0;
  parkedCount = 0;
  moneyMaking = false;
  moneyTarget = "Man";
  skipRequested = false;
  died = false;
  deaths = 0;
  startedAt = Date.now();
  qpAtStart = null;
  completed = 0;
  stepSince = Date.now();
  questSince = Date.now();
  async onStart() {
    const hostClient = globalThis.rs2b0t?.client;
    if (hostClient) {
      attach(hostClient);
      BotHost.attach(hostClient);
    }
    await Execution.delayUntil(() => Game.ingame() && Game.tile() !== null, 0);
    this.startedAt = Date.now();
    this.stepSince = this.startedAt;
    this.questSince = this.startedAt;
    paintState.set(QUEST_HUD_MAX_KEY, "0");
    paintState.set("tabs:aio", "Current");
    const all = QUEST_DEFS.map((d) => d.record.id);
    const chosen = this.settings.list("quests", []).filter((id) => all.includes(id));
    this.picked = new Set(chosen.length > 0 ? chosen : all);
    this.on("chat.message", (e) => {
      if (DEATH_RE.test(e.text)) {
        this.died = true;
        this.deaths++;
      }
    });
    QuestLoadout.current = selectedLoadout(this.settings);
    QuestFood.name = this.foodItem();
    applyArravSettings({
      gang: this.settings.str("arravGang", "random"),
      partner: this.settings.str("arravPartner", ""),
      certs: this.settings.num("arravCerts", 2)
    });
    applyHeroSettings({ partner: this.settings.str("heroPartner", "") });
    applyLegendsSettings({ reward: this.settings.str("legendsReward", "Prayer") });
    Sustain.set(async () => {
      if (this.shouldEat()) {
        await this.eatOnce();
        return;
      }
      await prayerUpkeep();
    });
    EventSignal.setInterrupt(() => this.skipRequested || this.died);
    WelcomeDismisser.enable();
    const startTile = Game.tile();
    if (startTile && startTile.x >= 3072 && startTile.x <= 3136 && startTile.z >= 3072 && startTile.z <= 3136) {
      this.log("WARNING: Character is on Tutorial Island (3072..3136). Complete Tutorial Island before running mainland quests.");
    }
    if (Modals.isOpen(WELCOME_SCREEN)) {
      await Modals.close();
    }
    const queueNames = QUEST_DEFS.filter((d) => this.picked.has(d.record.id)).map((d) => d.record.name);
    this.log(`AIOQuester, queue: ${queueNames.join(", ") || "(none)"}`);
    this.add(new DismissWelcomeModal, new ContinueDialog, new EatFood(this), new MoneyMakingTask({
      log: (m) => this.log(m),
      noteMoneyMaking: (step, target) => this.noteMoneyMaking(step, target)
    }), new QuestEngine(this));
  }
  async onStop() {
    EventSignal.setInterrupt(null);
    Sustain.set(null);
    setQuestPrayer(null, null);
  }
  foodItem() {
    return this.settings.str("food", FALLBACK_FOOD);
  }
  verbose() {
    return this.settings.bool("verbose", true);
  }
  foodHeld() {
    const food = this.foodItem();
    return food ? Inventory.count(food) : 0;
  }
  sustainPolicy() {
    const quest = this.runningId ? defById(this.runningId) : undefined;
    return resolveSustainPolicy(this.foodItem(), quest?.sustain);
  }
  shouldEat() {
    if (needsMoneyMaking()) {
      return false;
    }
    return this.selectFood() !== null;
  }
  async eatOnce() {
    const selected = this.selectFood();
    if (!selected) {
      return;
    }
    const { item: food, action } = selected;
    this.status = `consuming ${food.name} (${Math.round(Skills.hpFraction() * 100)}% hp)`;
    const before = Skills.effective("hitpoints");
    if (!await food.interact(action)) {
      return;
    }
    await Execution.delayUntil(() => Skills.effective("hitpoints") > before, 3000);
  }
  selectFood() {
    return selectSustainConsumable(Inventory.items(), this.sustainPolicy().foods, Skills.effective("hitpoints"), Skills.level("hitpoints"));
  }
  grindTargets() {
    if (this.moneyMaking) {
      return [this.moneyTarget.toLowerCase()];
    }
    return this.runningId ? defById(this.runningId)?.grind ?? [] : [];
  }
  pickedIds() {
    return this.picked;
  }
  noteMoneyMaking(step, target) {
    this.moneyMaking = true;
    this.status = MONEY_MAKING_LABEL;
    if (step !== this.stepDesc) {
      this.stepSince = Date.now();
    }
    this.stepDesc = step;
    if (target) {
      this.moneyTarget = target;
    }
  }
  noteState(rows, runningId, stepDesc, noProgress, parked) {
    this.moneyMaking = false;
    if (stepDesc !== this.stepDesc) {
      this.stepSince = Date.now();
    }
    if (questClockRestarts(this.runningId, runningId)) {
      this.questSince = Date.now();
    }
    if (runningId !== this.runningId) {
      const quest = runningId ? defById(runningId) : undefined;
      setQuestPrayer(quest?.pray, (m) => this.log(`${quest?.record.name ?? "quest"}: ${m}`));
    }
    const done = rows.filter((r) => r.status === "DONE").length;
    const wasDone = this.rows.filter((r) => r.status === "DONE").length;
    if (this.rows.length > 0 && done > wasDone) {
      this.completed += done - wasDone;
    }
    this.rows = rows;
    this.runningId = runningId;
    this.stepDesc = stepDesc;
    this.noProgress = noProgress;
    this.parkedCount = parked;
    const running = rows.find((r) => r.id === runningId);
    this.status = running ? `running ${running.name}` : stepDesc;
  }
  requestSkip() {
    if (this.skipRequested) {
      return;
    }
    this.skipRequested = true;
    const name = this.rows.find((r) => r.id === this.runningId)?.name ?? this.runningId ?? "current quest";
    this.log(`Skip quest, abandoning ${name} after the current step yields`);
  }
  skipPending() {
    return this.skipRequested;
  }
  consumeSkip() {
    const s = this.skipRequested;
    this.skipRequested = false;
    return s;
  }
  consumeDeath() {
    const d = this.died;
    this.died = false;
    return d;
  }
  finish(reason) {
    ScriptRunner.stop(reason);
  }
  onPaint(ctx) {
    const qp = Quests.points();
    if (this.qpAtStart === null && qp > 0) {
      this.qpAtStart = qp;
    }
    if (queueWaitingOnSkills(this.rows)) {
      paintSkillGateBanner(ctx, skillBlockedQuests(this.rows));
    }
    paintQuestJournal(ctx, {
      status: this.status,
      rows: this.rows,
      runningId: this.runningId,
      stepDesc: this.stepDesc,
      noProgress: this.noProgress,
      parkedCount: this.parkedCount,
      startedAt: this.startedAt,
      stepSince: this.stepSince,
      questSince: this.questSince,
      completed: this.completed,
      deaths: this.deaths,
      qp,
      qpGained: this.qpAtStart === null ? 0 : qp - this.qpAtStart,
      skipRequested: this.skipRequested,
      foodLabel: `${this.foodItem() ?? "none"} x${this.foodHeld()}`,
      loadout: QuestLoadout.current?.name ?? "none",
      runnerState: ScriptRunner.state,
      onSkip: () => this.requestSkip()
    });
  }
}

class EatFood {
  bot;
  constructor(bot) {
    this.bot = bot;
  }
  validate() {
    return this.bot.shouldEat();
  }
  async execute() {
    await this.bot.eatOnce();
  }
}

class DismissWelcomeModal {
  validate() {
    return Modals.isOpen(WELCOME_SCREEN);
  }
  async execute() {
    await Modals.close();
  }
}

