var QUEST_ID = "elemental_workshop";
function settingsForQuest() {
  const settings = { ...AIO_SETTINGS };
  delete settings.quests;
  if (QUEST_ID !== "blackarmgang" && QUEST_ID !== "hero") {
    delete settings.arravGang;
  }
  if (QUEST_ID !== "blackarmgang") {
    delete settings.arravPartner;
    delete settings.arravCerts;
  }
  if (QUEST_ID !== "hero") {
    delete settings.heroPartner;
  }
  if (QUEST_ID !== "legends") {
    delete settings.legendsReward;
  }
  return settings;
}
var ElementalWorkshop_default = defineBot({
  name: "Elemental Workshop",
  description: "Complete " + "Elemental Workshop" + " — gathers or buys required items and runs the quest to journal-complete (AIOQuester engine from rs2b2t/rs2b0t).",
  category: "Quest",
  tags: ["quest", "aioquester"],
  version: "2.0.0",
  settingsSchema: settingsForQuest(),
  create: () => new AIOQuester
});
export {
  ElementalWorkshop_default as default
};
